(function(G){const D=(G.DND=G.DND||{});D.INC_XAN=[{"id":"abilita-potenziata","nome":"Abilità Potenziata","eng":"","liv":5,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Contatto","comp":"V, S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["bardo","mago","stregone"],"desc":["Tocca una creatura consenziente per farle raddoppiare il bonus di competenza nelle prove di un'abilità in cui è già competente, a scelta dell'incantatore, finché dura la concentrazione."],"alto":"","fonte":"xge","sintesi":true},{"id":"aculeo-mentale","nome":"Aculeo Mentale","eng":"","liv":2,"scuola":"Divinazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["mago","stregone","warlock"],"desc":["Con un tiro salvezza su Saggezza, il bersaglio subisce danni psichici, dimezzati se lo supera; se fallisce, l'incantatore ne localizza la posizione e non può nascondersi da lui."],"alto":"","fonte":"xge","sintesi":true},{"id":"anatema-elementale","nome":"Anatema Elementale","eng":"","liv":4,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","mago","warlock"],"desc":["Segna un nemico visibile a distanza: se fallisce il TS su Costituzione, ogni turno in cui subisce il tipo di danno scelto riceve 2d6 extra e perde la resistenza a quel tipo."],"alto":"","fonte":"xge","sintesi":true},{"id":"arma-sacra","nome":"Arma Sacra","eng":"","liv":5,"scuola":"Invocazione","rituale":false,"tempo":"1 azione bonus","gittata":"Contatto","comp":"V, S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["chierico","paladino"],"desc":["L'arma toccata si carica di energia radiosa: illumina l'area, colpisce con danni radiosi extra e, se non è già magica, lo diventa. Con un'azione bonus il lancio può esplodere in un'ondata che ferisce e acceca le creature entro 9 metri dall'arma che falliscono il tiro su Costituzione (errata 2020: la distanza si misura dall'arma)."],"alto":"","fonte":"xge","sintesi":true},{"id":"assorbire-elementi","nome":"Assorbire Elementi","eng":"","liv":1,"scuola":"Abiurazione","rituale":false,"tempo":"1 reazione, quando l'incantatore subisce danni da acido, freddo, fulmine, fuoco o tuono","gittata":"Personale","comp":"S","durata":"1 round","conc":false,"classi":["druido","mago","ranger","stregone"],"desc":["Quando l'incantatore riceve danni elementali, li attutisce e ottiene resistenza a quel tipo fino al suo turno successivo; il primo colpo in mischia di quel turno infligge 1d6 danni extra dello stesso tipo, e l'incantesimo termina. Con uno slot superiore, il danno extra cresce di 1d6 per ogni livello sopra il primo."],"alto":"","fonte":"xge","sintesi":true},{"id":"boschetto-druidico","nome":"Boschetto Druidico","eng":"","liv":6,"scuola":"Abiurazione","rituale":false,"tempo":"10 minuti","gittata":"Contatto","comp":"V, S, M (vischio consumato dall'incantesimo, raccolto con un falcetto d'oro alla luce della luna piena)","durata":"24 ore","conc":false,"classi":["druido"],"desc":["Protegge un'area all'aperto o sotterranea con nebbia, rovi intralcianti, alberi guardiani e venti o spine magiche, che possono essere disattivati solo uno alla volta."],"alto":"","fonte":"xge","sintesi":true},{"id":"catapulta","nome":"Catapulta","eng":"","liv":1,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"S","durata":"Istantanea","conc":false,"classi":["mago","stregone"],"desc":["Scaglia un oggetto leggero, non indossato né portato, fino a 27 metri in linea retta. Se colpisce una creatura che non riesce a evitarlo, vi resta conficcato; in ogni caso infligge 3d8 danni contundenti."],"alto":"","fonte":"xge","sintesi":true},{"id":"cerimonia","nome":"Cerimonia","eng":"","liv":1,"scuola":"Abiurazione","rituale":true,"tempo":"1 ora","gittata":"Contatto","comp":"V, S, M (polvere argentata da 25 mo, consumata dall'incantesimo)","durata":"Istantanea","conc":false,"classi":["chierico","paladino"],"desc":["Con un rito sacro carico di magia, il lanciatore può benedire l'acqua, consacrare un umanoide alla propria divinità, riportare l'allineamento originale di una creatura o proteggere un defunto dal diventare non morto. Alcuni riti danno bonus temporanei ai tiri salvezza, alle prove di caratteristica o alla CA."],"alto":"","fonte":"xge","sintesi":true},{"id":"charme-sui-mostri","nome":"Charme sui Mostri","eng":"","liv":4,"scuola":"Ammaliamento","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V, S","durata":"1 ora","conc":false,"classi":["bardo","druido","mago","stregone","warlock"],"desc":["Una creatura visibile entro 9 metri deve superare un tiro salvezza su Saggezza, con vantaggio se combatte contro l'incantatore o i suoi alleati. Se fallisce, lo considera un amico e resta affascinata finché la durata non scade o non subisce danni da lui o dai suoi alleati."],"alto":"","fonte":"xge","sintesi":true},{"id":"collera-della-natura","nome":"Collera della Natura","eng":"","liv":5,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","ranger"],"desc":["Evoca spiriti naturali che animano alberi, rocce ed erba in un'area cubica: i nemici vicini agli alberi subiscono danni dai rami, quelli sul terreno possono essere intrappolati dalle radici e una roccia può essere scagliata contro un bersaglio."],"alto":"","fonte":"xge","sintesi":true},{"id":"colpo-del-vento-dacciaio","nome":"Colpo del Vento d’Acciaio","eng":"","liv":5,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"S, M (un'arma da mischia del valore di almeno 1 mo)","durata":"Istantanea","conc":false,"classi":["mago","ranger"],"desc":["Chi lancia sparisce brandendo l'arma del lancio e colpisce fino a cinque nemici visibili entro 9 metri con attacchi di forza, poi riappare vicino a uno dei bersagli."],"alto":"","fonte":"xge","sintesi":true},{"id":"colpo-dello-zefiro","nome":"Colpo dello Zefiro","eng":"","liv":1,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione bonus","gittata":"Personale","comp":"V","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["ranger"],"desc":["Mentre dura, lo spostamento non provoca attacchi di opportunità; una volta può ottenere vantaggio su un attacco con arma, che se colpisce infligge 1d8 danni da forza extra, e la velocità aumenta di 9 metri fino a fine turno."],"alto":"","fonte":"xge","sintesi":true},{"id":"coltello-di-ghiaccio","nome":"Coltello di Ghiaccio","eng":"","liv":1,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"S, M (una goccia d'acqua o un frammento di ghiaccio)","durata":"Istantanea","conc":false,"classi":["druido","mago","stregone"],"desc":["Un proiettile di ghiaccio colpisce un bersaglio a distanza causando danni perforanti; poi esplode e chi si trova vicino deve resistere con Destrezza o subire danni da freddo."],"alto":"","fonte":"xge","sintesi":true},{"id":"controllare-fiamme","nome":"Controllare Fiamme","eng":"","liv":0,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"S","durata":"Istantanea o 1 ora","conc":false,"classi":["druido","mago","stregone"],"desc":["Spegne o allunga una fiamma non magica a portata, oppure ne cambia luce e colore e vi fa comparire figure animate per un'ora."],"alto":"","fonte":"xge","sintesi":true},{"id":"controllare-venti","nome":"Controllare Venti","eng":"","liv":5,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"90 metri","comp":"V, S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["druido","mago","stregone"],"desc":["Permette di modellare il vento in un cubo da 30 metri visibile entro gittata, scegliendo correnti orizzontali, raffiche verso l'alto o verso il basso, e potenziando i salti delle creature al suo interno."],"alto":"","fonte":"xge","sintesi":true},{"id":"corona-di-stelle","nome":"Corona di Stelle","eng":"","liv":7,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S","durata":"1 ora","conc":false,"classi":["mago","stregone","warlock"],"desc":["Sette luci orbitanti ruotano intorno al capo del lanciatore; con un'azione bonus ne scaglia una contro un bersaglio entro 36 metri con un attacco a distanza che, se va a segno, infligge 4d12 danni radiosi. Ogni scintilla si consuma comunque, e usare uno slot superiore ne aggiunge altre due."],"alto":"","fonte":"xge","sintesi":true},{"id":"alba","nome":"Alba","eng":"","liv":5,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S, M (un pendente raffigurante un sole splendente del valore di almeno 100 mo)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["chierico","mago"],"desc":["Appare un cilindro di luce solare alto 12 metri e con raggio di 9 metri: le creature all'interno subiscono 4d10 danni radiosi (TS Costituzione per metà) quando appare e a fine turno; l'incantatore può spostarlo di 18 metri con un'azione bonus."],"alto":"","fonte":"xge","sintesi":true},{"id":"creare-falo","nome":"Creare Falò","eng":"","liv":0,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","mago","stregone","warlock"],"desc":["Accende un cubo di fuoco di 1,5 metri a distanza: chi si trova nell'area o vi entra deve superare un tiro salvezza su Destrezza o subire danni da fuoco, che crescono con il livello e possono incendiare oggetti infiammabili."],"alto":"","fonte":"xge","sintesi":true},{"id":"creare-omuncolo","nome":"Creare Omuncolo","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 ora","gittata":"Contatto","comp":"V, S, M (argilla, cenere e radice di mandragora, che l'incantesimo consuma tutte, e un pugnale ingioiellato del valore di almeno 1.000 mo)","durata":"Istantanea","conc":false,"classi":["mago"],"desc":["L'incantatore si ferisce con un pugnale prezioso e trasforma i materiali e il proprio sangue in un omuncolo costrutto leale, che muore se lui muore. Dopo ogni riposo lungo può cedere parte dei suoi punti ferita massimi al costrutto, che li riceve come punti ferita propri."],"alto":"","fonte":"xge","sintesi":true},{"id":"danza-macabra","nome":"Danza Macabra","eng":"","liv":5,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["mago","warlock"],"desc":["Rianima fino a cinque cadaveri di taglia Media o Piccola entro gittata, trasformandoli in zombi o scheletri che l'incantatore controlla e può dirigere con un'azione bonus."],"alto":"","fonte":"xge","sintesi":true},{"id":"dardo-di-caos","nome":"Dardo di Caos","eng":"","liv":1,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["stregone"],"desc":["Un attacco a distanza che lancia energia caotica al bersaglio; il tipo di danno dipende dai dadi e, con due risultati uguali, il colpo rimbalza su un'altra creatura vicina."],"alto":"","fonte":"xge","sintesi":true},{"id":"debilitazione","nome":"Debilitazione","eng":"","liv":5,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone","warlock"],"desc":["Un tentacolo d'ombra colpisce un bersaglio visibile e ne prosciuga la vitalità con danni necrotici. Se il bersaglio fallisce il tiro salvezza su Destrezza, chi lancia può ripetere il danno ad ogni turno e guarire parte di quanto infligge."],"alto":"","fonte":"xge","sintesi":true},{"id":"diavoletto-di-polvere","nome":"Diavoletto di Polvere","eng":"","liv":2,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S, M (un pizzico di polvere)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","mago","stregone"],"desc":["Crea un piccolo vortice di polvere che danneggia e spinge chi gli sta vicino a fine turno, e può essere spostato con un'azione bonus, sollevando detriti che oscurano la zona."],"alto":"","fonte":"xge","sintesi":true},{"id":"disperdere","nome":"Disperdere","eng":"","liv":6,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V","durata":"Istantanea","conc":false,"classi":["mago","stregone","warlock"],"desc":["Teletrasporta fino a cinque creature visibili entro 9 metri. Le creature ostili possono resistere con un tiro salvezza su Saggezza, e quelle che subiscono l'effetto finiscono in uno spazio libero a terra o su un piano entro 36 metri dall'incantatore."],"alto":"","fonte":"xge","sintesi":true},{"id":"drago-illusorio","nome":"Drago Illusorio","eng":"","liv":8,"scuola":"Illusione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago"],"desc":["Evoca un drago d'ombra illusorio che può spaventare i nemici che lo vedono e, quando si muove, scaglia un cono di energia che danneggia chi si trova davanti; il drago non può essere ferito."],"alto":"","fonte":"xge","sintesi":true},{"id":"eruzione-terrestre","nome":"Eruzione Terrestre","eng":"","liv":3,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S, M (un frammento d'ossidiana)","durata":"Istantanea","conc":false,"classi":["druido","mago","stregone"],"desc":["Fa sgorgare terra e rocce in un cubo da 6 metri, infliggendo danni contundenti a chi fallisce un TS su Destrezza (metà se lo supera) e lasciando il terreno impervio finché non viene sgomberato."],"alto":"","fonte":"xge","sintesi":true},{"id":"evoca-demone-maggiore","nome":"Evoca Demone Maggiore","eng":"","liv":4,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S, M (fiala di sangue di un umanoide ucciso nelle ultime 24 ore)","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["mago","warlock"],"desc":["Richiama un demone dell'Abisso di grado di sfida fino a 5 che agisce secondo i comandi verbali dell'incantatore; se lasciato libero attacca chi gli è vicino, mentre un cerchio di sangue tiene lontana la creatura."],"alto":"","fonte":"xge","sintesi":true},{"id":"evoca-demoni-minori","nome":"Evoca Demoni Minori","eng":"","liv":3,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S, M (una fiala di sangue di un umanoide ucciso entro le ultime 24 ore)","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["mago","warlock"],"desc":["Chi lancia richiama un gruppo di demoni minori dall'Abisso, in numero variabile secondo un tiro di d6, che attaccano le creature non demoniache e ostili a tutti, incluso l'evocatore. Un cerchio di sangue tracciato a terra blocca i demoni e impedisce loro di colpire chi si trova al suo interno."],"alto":"","fonte":"xge","sintesi":true},{"id":"ferocia-primordiale","nome":"Ferocia Primordiale","eng":"","liv":0,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"S","durata":"Istantanea","conc":false,"classi":["druido"],"desc":["Con magia primordiale, il lanciatore fa crescere artigli o zanne e colpisce in mischia un nemico vicino, causando danni da acido che salgono con il livello."],"alto":"","fonte":"xge","sintesi":true},{"id":"flusso-di-energia-negativa","nome":"Flusso di Energia Negativa","eng":"","liv":5,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, M (un osso spezzato e un quadretto di seta nera)","durata":"Istantanea","conc":false,"classi":["mago","warlock"],"desc":["Scaglia filamenti di energia necrotica contro una creatura visibile a distanza: i non morti ricevono punti ferita temporanei, mentre gli altri rischiano molti danni con un tiro salvezza su Costituzione. Chi muore così torna come zombi."],"alto":"","fonte":"xge","sintesi":true},{"id":"folata","nome":"Folata","eng":"","liv":0,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["druido","mago","stregone"],"desc":["Con un gesto di pugno, l'incantatore crea una raffica d'aria che può respingere una creatura Media o più piccola se fallisce un TS su Forza, oppure spostare un oggetto leggero non custodito, senza causare danni."],"alto":"","fonte":"xge","sintesi":true},{"id":"fortezza-possente","nome":"Fortezza Possente","eng":"","liv":8,"scuola":"Evocazione","rituale":false,"tempo":"1 minuto","gittata":"1,5 km","comp":"V, S, M (un diamante da almeno 500 mo, consumato dall'incantesimo)","durata":"Istantanea","conc":false,"classi":["mago"],"desc":["Erige una fortezza di pietra con torri, mura e una rocca interna su un'area sgombra a vista, dotata di servitori invisibili e provviste; crolla dopo 7 giorni, ma lanciandola ogni 7 giorni per un anno diventa permanente."],"alto":"","fonte":"xge","sintesi":true},{"id":"frecce-infuocate","nome":"Frecce Infuocate","eng":"","liv":3,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Contatto","comp":"V, S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["druido","mago","ranger","stregone"],"desc":["Chi lancia l'incantesimo incanta una faretra: ogni freccia o quadrello estratto da essa e che colpisce un bersaglio infligge danni da fuoco extra, con l'incantesimo che termina dopo 12 munizioni usate."],"alto":"","fonte":"xge","sintesi":true},{"id":"fulgore-nauseante","nome":"Fulgore Nauseante","eng":"","liv":4,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago","stregone","warlock"],"desc":["Avvolge un'area sferica di 9 metri in un bagliore verdastro: chi vi entra o vi inizia il turno subisce danni radiosi e un livello di indebolimento, salvo superare un tiro salvezza su Costituzione, e non può restare invisibile."],"alto":"","fonte":"xge","sintesi":true},{"id":"gabbia-dellanima","nome":"Gabbia dell’Anima","eng":"","liv":6,"scuola":"Necromanzia","rituale":false,"tempo":"1 reazione, da effettuare quando vedi morire un umanoide entro 18 metri","gittata":"18 metri","comp":"V, S, M (una minuscola gabbia d'argento da 100 mo)","durata":"8 ore","conc":false,"classi":["mago","warlock"],"desc":["Catturi l'anima di un umanoide appena morto in una gabbia, che puoi sfruttare fino a sei volte per curarti, interrogarla, ottenere un vantaggio temporaneo o spiare i luoghi che conosceva in vita."],"alto":"","fonte":"xge","sintesi":true},{"id":"guardiano-della-natura","nome":"Guardiano della Natura","eng":"","liv":4,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione bonus","gittata":"Personale","comp":"V","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","ranger"],"desc":["L'incantatore si trasforma in una bestia primordiale, che potenzia velocità, vista e attacchi, oppure in un grande albero, che offre punti ferita temporanei, vantaggi difensivi e terreno difficile attorno a sé."],"alto":"","fonte":"xge","sintesi":true},{"id":"immolazione","nome":"Immolazione","eng":"","liv":5,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"V","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone"],"desc":["Un nemico visibile entro gittata viene avvolto dal fuoco: con un tiro salvezza su Destrezza riuscito subisce meno danni, altrimenti brucia e ripete il tiro a ogni suo turno."],"alto":"","fonte":"xge","sintesi":true},{"id":"incuti-paura","nome":"Incuti Paura","eng":"","liv":1,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","warlock"],"desc":["Il bersaglio, se fallisce un tiro salvezza su Saggezza, si spaventa di chi lancia e può ripetere il tiro a ogni suo turno; costrutti e non morti sono immuni. Con slot superiori si colpiscono più creature vicine tra loro."],"alto":"","fonte":"xge","sintesi":true},{"id":"infestazione","nome":"Infestazione","eng":"","liv":0,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V, S, M (una pulce viva)","durata":"Istantanea","conc":false,"classi":["druido","mago","stregone","warlock"],"desc":["Il bersaglio tenta un tiro salvezza su Costituzione o subisce danni da veleno e viene spinto di 1,5 metri in una direzione decisa da un d4; i danni crescono con il livello."],"alto":"","fonte":"xge","sintesi":true},{"id":"interdizione-primordiale","nome":"Interdizione Primordiale","eng":"","liv":6,"scuola":"Abiurazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido"],"desc":["Per la durata concede resistenza a cinque tipi di danno elementale; con la reazione può trasformarla in immunità a quel tipo, che resta fino al turno successivo dell'incantatore."],"alto":"","fonte":"xge","sintesi":true},{"id":"investitura-del-ghiaccio","nome":"Investitura del Ghiaccio","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["druido","mago","stregone","warlock"],"desc":["Avvolge chi lancia in uno strato di ghiaccio, rendendolo immune al freddo e resistente al fuoco e facilitando il movimento sul terreno ghiacciato. Può anche scagliare un cono di vento gelido che infligge 4d6 danni da freddo, dimezzati con un tiro salvezza su Costituzione, e rallenta chi fallisce."],"alto":"","fonte":"xge","sintesi":true},{"id":"investitura-del-vento","nome":"Investitura del Vento","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["druido","mago","stregone","warlock"],"desc":["Il lanciatore si circonda di un turbine che rende più difficili i colpi a distanza contro di lui e gli concede volo; con un'azione può generare un cubo di vento che danneggia e spinge le creature al suo interno."],"alto":"","fonte":"xge","sintesi":true},{"id":"investitura-della-fiamma","nome":"Investitura della Fiamma","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["druido","mago","stregone","warlock"],"desc":["Avvolge chi lancia in fiamme che illuminano l'area e lo rendono immune al fuoco e resistente al freddo; chi gli si avvicina si scotta, e lui può scagliare una linea di fuoco che colpisce chi si trova sul suo percorso."],"alto":"","fonte":"xge","sintesi":true},{"id":"investitura-della-pietra","nome":"Investitura della Pietra","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["druido","mago","stregone","warlock"],"desc":["Il lanciatore si ricopre di detriti rocciosi e resiste ai danni fisici non magici. Può scatenare un piccolo sisma che fa cadere a terra le creature vicine e muoversi attraverso la pietra, ma se vi si ferma viene espulso e resta stordito."],"alto":"","fonte":"xge","sintesi":true},{"id":"invulnerabilita","nome":"Invulnerabilità","eng":"","liv":9,"scuola":"Abiurazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S, M (frammento di adamantio da almeno 500 mo, consumato dall'incantesimo)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago"],"desc":["Rende chi lo lancia impossibile da ferire per tutta la durata, finché mantiene la concentrazione sull'incantesimo."],"alto":"","fonte":"xge","sintesi":true},{"id":"lama-dombra","nome":"Lama d’Ombra","eng":"","liv":2,"scuola":"Illusione","rituale":false,"tempo":"1 azione bonus","gittata":"Personale","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone","warlock"],"desc":["Crea nella mano dell'incantatore una spada di tenebra che infligge danni psichici e concede vantaggio contro bersagli in penombra o al buio; il danno cresce con slot di livello superiore."],"alto":"","fonte":"xge","sintesi":true},{"id":"legame-con-le-bestie","nome":"Legame con le Bestie","eng":"","liv":1,"scuola":"Divinazione","rituale":false,"tempo":"1 azione","gittata":"Contatto","comp":"V, S, M (un ciuffo di pelliccia avvolto in un pezzo di stoffa)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["druido","ranger"],"desc":["Crea un legame mentale con una bestia affascinata o amichevole con Intelligenza inferiore a 4; finché dura, la bestia capta i messaggi, invia emozioni semplici e ottiene vantaggio contro i nemici vicini al lanciatore."],"alto":"","fonte":"xge","sintesi":true},{"id":"maelstrom","nome":"Maelstrom","eng":"","liv":5,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S, M (un foglio di carta o una foglia a forma di imbuto)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido"],"desc":["Evoca un vortice d'acqua in un'area di 9 metri, rendendola terreno difficile: chi inizia il turno lì deve reggere un tiro salvezza su Forza o subire 6d6 danni contundenti e essere trascinato verso il centro."],"alto":"","fonte":"xge","sintesi":true},{"id":"metamorfosi-di-massa","nome":"Metamorfosi di Massa","eng":"","liv":9,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S, M (il bozzolo di un bruco)","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["bardo","mago","stregone"],"desc":["Trasforma fino a dieci creature visibili in bestie a scelta del lanciatore, con tiro salvezza di Saggezza per chi non è consenziente. Ottengono PF temporanei pari alla nuova forma, ma restano limitate nelle azioni e non possono usare l'equipaggiamento."],"alto":"","fonte":"xge","sintesi":true},{"id":"minuscole-meteore-di-melf","nome":"Minuscole Meteore di Melf","eng":"","liv":3,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S, M (salnitro, zolfo e pece di pino mescolati in una biglia)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago","stregone"],"desc":["Sei piccole meteore ruotano attorno al lanciatore e possono essere scagliate contro punti entro 36 metri, esplodendo e infliggendo danni da fuoco a chi si trova vicino, con una salvezza su Destrezza che dimezza il danno."],"alto":"","fonte":"xge","sintesi":true},{"id":"modellare-acqua","nome":"Modellare Acqua","eng":"","liv":0,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"S","durata":"Istantanea o 1 ora","conc":false,"classi":["druido","mago","stregone"],"desc":["Permette di spostare, plasmare o congelare l'acqua in un cubo di 1,5 metri, oppure cambiarne colore e trasparenza per un'ora."],"alto":"","fonte":"xge","sintesi":true},{"id":"modellare-terra","nome":"Modellare Terra","eng":"","liv":0,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"S","durata":"Istantanea o 1 ora","conc":false,"classi":["druido","mago","stregone"],"desc":["Permette di spostare brevemente la terra o plasmare pietra e suolo a distanza, senza causare danni, oppure di alterarne l'aspetto o il tipo di terreno per un'ora. Con più lanci attivi, si possono mantenere al massimo due effetti non istantanei alla volta."],"alto":"","fonte":"xge","sintesi":true},{"id":"morsa-del-gelo","nome":"Morsa del Gelo","eng":"","liv":0,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["druido","mago","stregone","warlock"],"desc":["Un colpo di gelo a un bersaglio visibile in gittata: se fallisce il tiro salvezza su Costituzione, subisce danni da freddo e ha svantaggio su un attacco con arma prima della fine del suo turno successivo; i danni crescono al 5°, 11° e 17° livello."],"alto":"","fonte":"xge","sintesi":true},{"id":"muro-di-luce","nome":"Muro di Luce","eng":"","liv":5,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S, M (uno specchietto)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago","stregone","warlock"],"desc":["Crea un muro di luce orientabile, lungo fino a 18 metri, che acceca e ferisce con danni radiosi chi attraversa la sua area. Finché dura, l'incantatore può usarlo per colpire nemici a distanza, accorciandolo a ogni colpo."],"alto":"","fonte":"xge","sintesi":true},{"id":"nemici-in-abbondanza","nome":"Nemici in Abbondanza","eng":"","liv":3,"scuola":"Ammaliamento","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["bardo","mago","stregone","warlock"],"desc":["Il bersaglio visibile, se fallisce un tiro su Intelligenza, vede ogni creatura come nemica e attacca a caso chi gli sta intorno. Ogni danno subito gli dà una nuova possibilità di liberarsi dall'effetto."],"alto":"","fonte":"xge","sintesi":true},{"id":"ombra-di-moil","nome":"Ombra di Moil","eng":"","liv":4,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S, M (il globo oculare di un non morto racchiuso in una gemma da almeno 150 mo)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["warlock"],"desc":["Avvolge chi lo lancia in ombre simili a fiamme che lo rendono quasi invisibile agli altri e scuriscono l'area intorno a lui; gli conferisce resistenza ai danni radiosi e punisce con danni necrotici chi lo attacca da vicino."],"alto":"","fonte":"xge","sintesi":true},{"id":"onda-di-marea","nome":"Onda di Marea","eng":"","liv":3,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S, M (una goccia d'acqua)","durata":"Istantanea","conc":false,"classi":["druido","mago","stregone"],"desc":["Crea un'ondata che investe un'area lunga fino a 9 metri: chi fallisce il tiro su Destrezza subisce 4d8 danni contundenti e cade a terra, mentre chi riesce ne subisce la metà senza cadere. Spegne anche le fiamme libere vicine."],"alto":"","fonte":"xge","sintesi":true},{"id":"orrido-avvizzimento-di-abi-dalzim","nome":"Orrido Avvizzimento di Abi-Dalzim","eng":"","liv":8,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"45 metri","comp":"V, S, M (un frammento di spugna)","durata":"Istantanea","conc":false,"classi":["mago","stregone"],"desc":["Prosciuga i liquidi da tutte le creature in un cubo di 9 metri scelto a vista: chi fallisce il tiro su Costituzione subisce 12d8 danni necrotici, chi lo supera ne subisce la metà. Costrutti e non morti sono immuni, mentre piante non magiche avvizziscono all'istante."],"alto":"","fonte":"xge","sintesi":true},{"id":"oscurita-della-follia","nome":"Oscurità della Follia","eng":"","liv":8,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"45 metri","comp":"V, M (una goccia di pece mescolata a una goccia di mercurio)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago","warlock"],"desc":["Genera una sfera di tenebre da 18 metri di raggio che acceca anche chi ha scurovisione e spegne le luci comuni o di livello 8 o inferiore. Chi inizia il turno al suo interno deve superare un tiro salvezza su Saggezza o subire danni psichici, dimezzati se riesce."],"alto":"","fonte":"xge","sintesi":true},{"id":"ossa-della-terra","nome":"Ossa della Terra","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["druido"],"desc":["Fa sorgere fino a sei pilastri di pietra visibili entro gittata, che possono sollevare una creatura sopra di essi o schiacciarla se non raggiungono l'altezza piena, lasciando poi detriti che rendono difficile il terreno."],"alto":"","fonte":"xge","sintesi":true},{"id":"parola-del-potere-dolore","nome":"Parola del Potere Dolore","eng":"","liv":7,"scuola":"Ammaliamento","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V","durata":"Istantanea","conc":false,"classi":["mago","stregone","warlock"],"desc":["Infligge dolore lancinante a un bersaglio visibile con 100 PF o meno: velocità ridotta a 3 metri, svantaggio su attacchi, prove e tiri salvezza non su Costituzione, e il lancio di incantesimi richiede un tiro salvezza su Costituzione. Il bersaglio può terminare l'effetto con un tiro salvezza su Costituzione a fine turno."],"alto":"","fonte":"xge","sintesi":true},{"id":"parola-radiosa","nome":"Parola Radiosa","eng":"","liv":0,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"1,5 metri","comp":"V, M (simbolo sacro)","durata":"Istantanea","conc":false,"classi":["chierico"],"desc":["Un bagliore radioso brucia le creature vicine che falliscono un tiro Costituzione, con danni che crescono ai livelli 5, 11 e 17."],"alto":"","fonte":"xge","sintesi":true},{"id":"passo-del-tuono","nome":"Passo del Tuono","eng":"","liv":3,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"V","durata":"Istantanea","conc":false,"classi":["mago","stregone","warlock"],"desc":["Permette di teletrasportarsi in un punto visibile a distanza, lasciando dietro di sé un boato che ferisce chi è vicino al punto di partenza, con un tiro su Costituzione per dimezzare il danno. Si può anche trasportare un alleato consenziente di taglia pari o inferiore e il proprio equipaggiamento."],"alto":"","fonte":"xge","sintesi":true},{"id":"passo-remoto","nome":"Passo Remoto","eng":"","liv":5,"scuola":"Evocazione","rituale":false,"tempo":"1 azione bonus","gittata":"Personale","comp":"V","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone","warlock"],"desc":["Permette di teletrasportarsi fino a 18 metri verso un punto libero visibile, ripetendo il balzo con un'azione bonus a ogni turno mentre si mantiene la concentrazione."],"alto":"","fonte":"xge","sintesi":true},{"id":"pietra-magica","nome":"Pietra Magica","eng":"","liv":0,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione bonus","gittata":"Contatto","comp":"V, S","durata":"1 minuto","conc":false,"classi":["druido","warlock"],"desc":["Rende magici fino a tre sassolini, che l'incantatore o un alleato può lanciare come attacco a distanza, a mano (18 m) o con una fionda. Ogni sasso perde l'effetto dopo un tentativo, a segno o meno."],"alto":"","fonte":"xge","sintesi":true},{"id":"pirotecnica","nome":"Pirotecnica","eng":"","liv":2,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["bardo","mago","stregone"],"desc":["Spegne le fiamme non magiche in un cubo di 1,5 metri entro gittata, poi crea un lampo di fuochi d'artificio che acceca le creature vicine oppure una densa nube di fumo nero che oscura l'area per un minuto."],"alto":"","fonte":"xge","sintesi":true},{"id":"prigione-mentale","nome":"Prigione Mentale","eng":"","liv":6,"scuola":"Illusione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone","warlock"],"desc":["Intrappola un bersaglio visibile in un'illusione che solo lui percepisce, infliggendogli danni psichici e bloccandolo. Se tenta di uscire o di colpire attraverso la barriera, subisce altri danni psichici e l'effetto svanisce."],"alto":"","fonte":"xge","sintesi":true},{"id":"richiamo-infernale","nome":"Richiamo Infernale","eng":"","liv":5,"scuola":"Evocazione","rituale":false,"tempo":"1 minuto","gittata":"27 metri","comp":"V, S, M (un rubino del valore di almeno 999 mo)","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["mago","warlock"],"desc":["Evoca un diavolo infernale di grado di sfida non superiore a 6, che può ubbidire ai comandi verbali solo se l'ordine lo attira o se l'incantatore supera una prova contrapposta; se la concentrazione cade, il diavolo resta ancora per un po' prima di svanire."],"alto":"","fonte":"xge","sintesi":true},{"id":"rintocco-dei-morti","nome":"Rintocco dei Morti","eng":"","liv":0,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["chierico","mago","warlock"],"desc":["Un bersaglio visibile entro 18 m deve riuscire in un tiro salvezza su Saggezza o subire danni necrotici, di 1d8 o di 1d12 se ha già perso punti ferita; i dadi aumentano con il livello."],"alto":"","fonte":"xge","sintesi":true},{"id":"rombo-di-tuono","nome":"Rombo di Tuono","eng":"","liv":0,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"1,5 metri","comp":"S","durata":"Istantanea","conc":false,"classi":["bardo","druido","mago","stregone","warlock"],"desc":["Produce un boato fragoroso che si sente da lontano e infligge danni da tuono alle creature vicine che falliscono un tiro salvezza su Costituzione; i danni aumentano con il livello."],"alto":"","fonte":"xge","sintesi":true},{"id":"sciame-di-palle-di-neve-di-snilloc","nome":"Sciame di Palle di Neve di Snilloc","eng":"","liv":2,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"V, S, M (un pezzo di ghiaccio o una scheggia di pietra bianca)","durata":"Istantanea","conc":false,"classi":["mago","stregone"],"desc":["Scaglia un nubifragio di proiettili gelati su un punto a scelta entro gittata; chi si trova nel raggio di 1,5 metri deve superare un tiro salvezza su Destrezza o subire 3d6 danni da freddo, dimezzati se riesce."],"alto":"","fonte":"xge","sintesi":true},{"id":"scossa-sinaptica","nome":"Scossa Sinaptica","eng":"","liv":5,"scuola":"Ammaliamento","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["bardo","mago","stregone","warlock"],"desc":["Un'esplosione psichica in un punto a 36 metri colpisce le creature entro 6 metri con un tiro salvezza su Intelligenza: chi fallisce subisce più danni e resta confuso per un minuto, mentre chi riesce ne subisce la metà."],"alto":"","fonte":"xge","sintesi":true},{"id":"scossa-tellurica","nome":"Scossa Tellurica","eng":"","liv":1,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"3 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["bardo","druido","mago","stregone"],"desc":["Una scossa nel terreno colpisce chi si trova nell'area tranne il lanciatore, che deve superare un tiro salvezza su Destrezza o subire 1d6 danni contundenti e finire a terra. Pietra e terra smossa diventano terreno difficile finché non vengono sgomberati."],"alto":"","fonte":"xge","sintesi":true},{"id":"scritta-celeste","nome":"Scritta Celeste","eng":"","liv":2,"scuola":"Trasmutazione","rituale":true,"tempo":"1 azione","gittata":"Vista","comp":"V, S","durata":"Concentrazione, massimo 1 ora","conc":true,"classi":["bardo","druido","mago"],"desc":["Forma fino a dieci parole di nuvole nel cielo visibile, che svaniscono alla fine. Un vento forte può disperderle e interrompere l'effetto in anticipo."],"alto":"","fonte":"xge","sintesi":true},{"id":"servitore-minuscolo","nome":"Servitore Minuscolo","eng":"","liv":3,"scuola":"Trasmutazione","rituale":false,"tempo":"1 minuto","gittata":"Contatto","comp":"V, S","durata":"8 ore","conc":false,"classi":["mago"],"desc":["Anima per 8 ore un piccolo oggetto inanimato non magico, che diventa un costrutto sotto il controllo dell'incantatore: può eseguirne gli ordini o difendersi dai nemici finché non viene ridotto a 0 punti ferita."],"alto":"","fonte":"xge","sintesi":true},{"id":"sfera-acquea","nome":"Sfera Acquea","eng":"","liv":4,"scuola":"Evocazione","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"V, S, M (una goccia d'acqua)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","mago","stregone"],"desc":["Richiama una grande sfera d'acqua che può risucchiare creature nel suo interno, costringendole a lottare per liberarsi con prove di Forza. L'incantatore può spostarla per trascinare o schiacciare i nemici, e quando l'effetto termina l'acqua si riversa al suolo facendo cadere a terra chi era intrappolato."],"alto":"","fonte":"xge","sintesi":true},{"id":"sfera-al-vetriolo","nome":"Sfera al Vetriolo","eng":"","liv":4,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"45 metri","comp":"V, S, M (una goccia di bile di una lumaca gigante)","durata":"Istantanea","conc":false,"classi":["mago","stregone"],"desc":["Un globo di acido verde esplode in un'area di 6 metri; chi la subisce fa un tiro salvezza su Destrezza, e chi fallisce riceve altro danno acido al turno successivo."],"alto":"","fonte":"xge","sintesi":true},{"id":"sfera-della-tempesta","nome":"Sfera della Tempesta","eng":"","liv":4,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"45 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone"],"desc":["Evoca un vortice d'aria che infligge danni contundenti a chi vi si trova o termina lì il turno, se fallisce la prova di Forza. Finché dura, l'incantatore può usare un'azione bonus per scagliare fulmini che colpiscono un bersaglio vicino alla sfera."],"alto":"","fonte":"xge","sintesi":true},{"id":"soffio-del-drago","nome":"Soffio del Drago","eng":"","liv":2,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione bonus","gittata":"Contatto","comp":"V, S, M (un peperoncino)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone"],"desc":["Il lanciatore concede a una creatura consenziente, capace di respirare, un soffio di acido, freddo, fulmine, fuoco o veleno in un cono di 4,5 metri. Chi fallisce il tiro su Destrezza subisce 3d6 danni, o la metà se lo supera, e il danno cresce con slot superiori."],"alto":"","fonte":"xge","sintesi":true},{"id":"sonnellino","nome":"Sonnellino","eng":"","liv":3,"scuola":"Ammaliamento","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"S, M (un pizzico di sabbia)","durata":"10 minuti","conc":false,"classi":["bardo","mago","stregone"],"desc":["Fa cadere in un sonno profondo alleati consenzienti visibili entro 9 metri, fino a tre; il sonno finisce se subiscono danni o vengono svegliati, e chi dorme per tutta la durata si riposa come in un riposo breve."],"alto":"","fonte":"xge","sintesi":true},{"id":"spirito-guaritore","nome":"Spirito Guaritore","eng":"","liv":2,"scuola":"Evocazione","rituale":false,"tempo":"1 azione bonus","gittata":"18 metri","comp":"V, S","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","ranger"],"desc":["Uno spirito naturale appare in un'area entro 18 metri e cura chi entra o inizia il turno al suo interno, con più guarigione usando slot superiori. Non cura costrutti né non morti, e l'incantatore può spostarlo con un'azione bonus. Errata 2020: lo spirito può curare 1 + il modificatore di caratteristica da incantatore (minimo due) volte, poi svanisce."],"alto":"","fonte":"xge","sintesi":true},{"id":"stretta-della-terra-di-maximilian","nome":"Stretta della Terra di Maximilian","eng":"","liv":2,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V, S, M (una mano in miniatura modellata in argilla)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["mago","stregone"],"desc":["Una mano di terra compressa afferra una creatura vicina, infliggendo danni contundenti e trattenendola. Il lanciatore può stritolarla o spostare la mano verso un altro bersaglio, mentre la vittima può liberarsi con una prova di Forza."],"alto":"","fonte":"xge","sintesi":true},{"id":"tempio-degli-dei","nome":"Tempio degli Dèi","eng":"","liv":7,"scuola":"Evocazione","rituale":false,"tempo":"1 ora","gittata":"36 metri","comp":"V, S, M (simbolo sacro del valore di almeno 5 mo)","durata":"24 ore","conc":false,"classi":["chierico"],"desc":["Il lanciatore fa sorgere un edificio sacro su un punto visibile; alcune creature faticano a entrarvi, e chi è dentro subisce penalità ai tiri ma recupera più punti ferita dalle cure magiche."],"alto":"","fonte":"xge","sintesi":true},{"id":"trabocchetto","nome":"Trabocchetto","eng":"","liv":1,"scuola":"Abiurazione","rituale":false,"tempo":"1 minuto","gittata":"Contatto","comp":"S, M (7,5 metri di corda, che l'incantesimo consuma)","durata":"8 ore","conc":false,"classi":["druido","mago","ranger"],"desc":["Una corda traccia sul pavimento un cerchio quasi invisibile: chi ci entra senza superare un tiro salvezza su Destrezza viene sollevato a testa in giù e trattenuto."],"alto":"","fonte":"xge","sintesi":true},{"id":"trasferimento-di-vita","nome":"Trasferimento di Vita","eng":"","liv":3,"scuola":"Necromanzia","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["chierico","mago"],"desc":["Chi lancia si ferisce da solo con 4d8 danni necrotici, che non possono essere ridotti in alcun modo (errata 2020), per curare una creatura visibile entro gittata, che recupera il doppio di quanto subito; con slot superiori il danno cresce."],"alto":"","fonte":"xge","sintesi":true},{"id":"trasformazione-di-tenser","nome":"Trasformazione di Tenser","eng":"","liv":6,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V, S, M (alcuni peli di un toro)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago"],"desc":["Per un breve periodo il mago diventa un guerriero improvvisato: ottiene punti ferita temporanei, colpisce con più forza e precisione e può attaccare due volte, ma non può lanciare incantesimi. Al termine rischia un calo di energie se fallisce un tiro salvezza su Costituzione."],"alto":"","fonte":"xge","sintesi":true},{"id":"trasmutare-roccia","nome":"Trasmutare Roccia","eng":"","liv":5,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"36 metri","comp":"V, S, M (argilla e acqua)","durata":"Finché dissolto","conc":false,"classi":["druido","mago"],"desc":["Ammorbidisce una zona di roccia in fango che intrappola chi ci cammina, oppure indurisce il fango o le sabbie mobili in pietra, bloccando chi vi si trova dentro."],"alto":"","fonte":"xge","sintesi":true},{"id":"trova-cavalcatura-superiore","nome":"Trova Cavalcatura Superiore","eng":"","liv":4,"scuola":"Evocazione","rituale":false,"tempo":"10 minuti","gittata":"9 metri","comp":"V, S","durata":"Istantanea","conc":false,"classi":["paladino"],"desc":["Richiama uno spirito sotto forma di un fidato destriero scelto tra alcune creature leggendarie, che l'incantatore può guidare in battaglia e far tornare in campo con un nuovo lancio."],"alto":"","fonte":"xge","sintesi":true},{"id":"turbine","nome":"Turbine","eng":"","liv":7,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"90 metri","comp":"V, M (una pagliuzza)","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","mago","stregone"],"desc":["Un vortice evocato a terra può essere spostato dall'incantatore e risucchia oggetti e creature, infliggendo danni contundenti e tenendo sospesi i bersagli più piccoli finché dura."],"alto":"","fonte":"xge","sintesi":true},{"id":"urlo-psichico","nome":"Urlo Psichico","eng":"","liv":9,"scuola":"Ammaliamento","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"S","durata":"Istantanea","conc":false,"classi":["bardo","mago","stregone","warlock"],"desc":["Fino a dieci creature visibili entro gittata affrontano un tiro salvezza su Intelligenza: chi fallisce subisce 14d6 danni psichici e resta stordito, mentre chi riesce ne subisce metà senza stordimento."],"alto":"","fonte":"xge","sintesi":true},{"id":"vampa-di-aganazzar","nome":"Vampa di Aganazzar","eng":"","liv":2,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"9 metri","comp":"V, S, M (una scaglia di drago rosso)","durata":"Istantanea","conc":false,"classi":["mago","stregone"],"desc":["Sprigiona una striscia di fuoco lunga 9 metri e larga 1,5 metri; chi si trova sul percorso effettua un tiro salvezza su Destrezza, subendo 3d8 danni da fuoco se fallisce o la metà se riesce, con danni maggiori usando slot superiori."],"alto":"","fonte":"xge","sintesi":true},{"id":"vento-di-interdizione","nome":"Vento di Interdizione","eng":"","liv":2,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"Personale","comp":"V","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["bardo","druido","mago","stregone"],"desc":["Crea una folata che segue chi lancia in un raggio di 3 metri, rendendo sordi gli occupanti, spegnendo le fiamme piccole, ostacolando il movimento altrui e disperdendo nebbie e gas. Gli attacchi a distanza che attraversano l'area hanno svantaggio."],"alto":"","fonte":"xge","sintesi":true},{"id":"vincolo-della-terra","nome":"Vincolo della Terra","eng":"","liv":2,"scuola":"Trasmutazione","rituale":false,"tempo":"1 azione","gittata":"90 metri","comp":"V","durata":"Concentrazione, massimo 1 minuto","conc":true,"classi":["druido","mago","stregone","warlock"],"desc":["Se il bersaglio fallisce un tiro salvezza su Forza, perde la capacità di volare; se si trova in aria, precipita di 18 metri a ogni round finché non atterra o l'effetto termina."],"alto":"","fonte":"xge","sintesi":true},{"id":"muro-dacqua","nome":"Muro d’Acqua","eng":"","liv":3,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"18 metri","comp":"V, S, M (una goccia d'acqua)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["druido","mago","stregone"],"desc":["Crea una parete d'acqua in un punto visibile a distanza: i proiettili che la attraversano sono ostacolati, il fuoco perde metà potenza e il gelo può trasformare parti del muro in blocchi resistenti."],"alto":"","fonte":"xge","sintesi":true},{"id":"muro-di-sabbia","nome":"Muro di Sabbia","eng":"","liv":3,"scuola":"Invocazione","rituale":false,"tempo":"1 azione","gittata":"27 metri","comp":"V, S, M (una manciata di sabbia)","durata":"Concentrazione, massimo 10 minuti","conc":true,"classi":["mago"],"desc":["Crea una parete di sabbia vorticosa, lunga fino a 9 m, alta e spessa fino a 3 m, che ostacola la vista ma non il passaggio. Chi si trova al suo interno è accecato e il suo movimento costa il triplo."],"alto":"","fonte":"xge","sintesi":true}];})(typeof globalThis!=="undefined"?globalThis:window);
